function Apply($r, $rp) { $pf = $rp.Range.ParagraphFormat; $r.ParagraphFormat.Alignment = $pf.Alignment; $r.ParagraphFormat.SpaceBefore = $pf.SpaceBefore; $r.ParagraphFormat.SpaceAfter = $pf.SpaceAfter; $r.ParagraphFormat.LeftIndent = $pf.LeftIndent; $r.ParagraphFormat.FirstLineIndent = $pf.FirstLineIndent; $f = $rp.Range.Font; $r.Font.Name = $f.Name; $r.Font.Size = $f.Size; $r.Font.Bold = $f.Bold; $r.Font.Italic = 0; $r.Font.Color = $f.Color }
$script:pos = $doc.Paragraphs.Item($last).Range.Start
function AddText($text, $kind) { $r = $doc.Range($script:pos, $script:pos); $r.InsertAfter($text + "`r"); if ($kind -eq 'h') { $r.Style = $hr.Style.NameLocal; Apply $r $hr } elseif ($kind -eq 'cap') { $r.Style = $br.Style.NameLocal; Apply $r $br; $r.ParagraphFormat.Alignment = 1; $r.Font.Bold = 1; $r.Font.Size = 10 } else { $r.Style = $br.Style.NameLocal; Apply $r $br }; $script:pos = $r.End }
function AddTable($lines) { $s = $script:pos; $r = $doc.Range($s, $s); $r.InsertAfter(($lines -join "`r") + "`r"); $rr = $doc.Range($s, $r.End); $rr.Style = $br.Style.NameLocal; $rr.Font.Size = 9; $rr.Font.Bold = 0; $rr.ParagraphFormat.Alignment = 0; $rr.ParagraphFormat.SpaceBefore = 0; $rr.ParagraphFormat.SpaceAfter = 0; $tb = $rr.ConvertToTable(1); $tb.Borders.Enable = 1; $tb.Rows.Item(1).Range.Font.Bold = 1; $tb.Rows.Item(1).Shading.BackgroundPatternColor = 15983321; $tb.AutoFitBehavior(2); $script:pos = $tb.Range.End }
function AddPic($key, $capText) { $s = $script:pos; $r = $doc.Range($s, $s); $r.InsertAfter("`r"); $pp = $doc.Range($s, $s); $pp.Style = $br.Style.NameLocal; $pp.ParagraphFormat.Alignment = 1; $pp.ParagraphFormat.FirstLineIndent = 0; $pp.ParagraphFormat.LeftIndent = 0; $pp.ParagraphFormat.SpaceBefore = 6
  $ins = $doc.InlineShapes.AddPicture("$jpg\$key.jpg", $false, $true, $doc.Range($s, $s)); $wd = 420.0; $ht = $wd * $sizes.$key.h / $sizes.$key.w; if ($ht -gt 580) { $ht = 580.0; $wd = $ht * $sizes.$key.w / $sizes.$key.h }; $ins.LockAspectRatio = 0; $ins.Width = $wd; $ins.Height = $ht
  $script:pos = $doc.Range($s, $s).Paragraphs.Item(1).Range.End; AddText $capText 'cap' }
